def f(g,bg,l):
    H,W=len(g),len(g[0]); o=[r[:] for r in g]
    br=[set(range(W)) | set() for _ in range(H)]  # placeholder
    hbr=[set() for _ in range(H)]; vbr=[set() for _ in range(W)]
    for r in range(H):
        cs=[c for c in range(W) if g[r][c]==l]
        hbr[r]={c for c in range(min(cs)+1,max(cs))}
    for c in range(W):
        rs=[r for r in range(H) if g[r][c]==l]
        vbr[c]={r for r in range(min(rs)+1,max(rs))}
