def solve(g,maxrun=3):
    H=len(g);W=len(g[0]);out=[r[:] for r in g];bg=g[0][0]
    cnt=Counter(v for r in g for v in r if v!=bg); lval=cnt.most_common(1)[0][0]
    for r in range(H):
        line=g[r]
        for a,b in runs_line(line,lval):
            ln=b-a+1
            if ln>=maxrun: continue
            lo=a-1; hi=b+1
            L=Lcount=0; R=Rcount=0
            # greedy: alternate? use tie: extend both ends alternately starting left
            seg=list(range(a,b+1))
            for _ in range(maxrun-ln):
                if Lcount<=Rcount:
                    if lo>=0 and g[lo][r]==bg: seg.insert(0,lo); Lcount+=1; lo-=1
                else:
                    if hi<W and g[r][hi]==bg: seg.append(hi); Rcount+=1; hi+=1
                if Lcount+Rcount==maxrun-ln and (Lcount>Rcount or (Lcount>=Rcount and lo<0)): break
                if Lcount+Rcount==maxrun-ln and (Rcount>Lcount or (Rcount>=Lcount and hi>=W)): break
            for c in seg:
                if out[r][c]==bg: out[r][c]=2
    for c in range(W):
        col=[g[r][c] for r in range(H)]
        for a,b in runs_line(col,lval):
            ln=b-a+1
            if ln>=maxrun: continue
            lo=a-1; hi=b+1
            seg=list(range(a,b+1))
            for _ in range(maxrun-ln):
                if seg[0]!=seg[-1]:
                    if lo>=0 and col[lo]==bg: seg.insert(0,lo); lo-=1
                else:
                    if hi<H and col[hi]==bg: seg.append(hi); hi+=1
                if seg[0]!=seg[-1] and lo>=0 and col[lo]==bg: seg.insert(0,lo); lo-=1
                if seg[0]==seg[-1] and hi<H and col[hi]==bg: seg.append(hi); hi+=1
            for r in seg:
                if out[r][c]==bg: out[r][c]=2
    return out
